import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.x6OtgAz_.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1791942359000}'),i={name:"guide.md"};function s(n,e,c,h,l,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Axios Cache Interceptor is an axios interceptor that caches responses. It lets you call axios as often as you need without overloading the network or writing your own error-prone cache.</p><p>Every request made through your axios instance passes through the interceptor, which decides whether to send it to the network or answer it with a cached response.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Axios runs interceptors before calling the adapter and again before returning the response to the caller. The adapter is the last step and performs the actual network call. Because this library is built on interceptors instead of a custom adapter, you can keep using any axios adapter you want.</p><p>Before a request reaches the adapter, the request interceptor checks, among other conditions:</p><ul><li>whether a valid cached response already exists;</li><li>whether the request should be cached at all (sometimes you don’t want caching, and that’s fine);</li><li>whether an identical request is already in flight, so this one can wait for its result.</li></ul><p>After the adapter returns a response, the response interceptor checks whether it belongs to a <em>cacheable</em> request, saves it to storage, resolves other requests waiting for the same resource and returns the response to the original caller.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>TTL, <code>Cache-Control</code>, <code>ETag</code>, <code>Last-Modified</code> and <code>Vary</code> support.</li><li>Returns the previous cached response when a new request fails.</li><li>Deduplicates concurrent requests for the same resource.</li><li>Configurable globally and per request.</li><li>Built-in in-memory, <code>localStorage</code> and <code>sessionStorage</code> storages.</li><li>Production UMD bundle of about 18 KiB minified (about 7 KiB gzipped), dependencies included.</li><li>A development build that logs why each request was or wasn’t cached.</li><li>In a 2023 benchmark with cached responses, served about 21x more requests per second than plain axios and about 9% more than <code>axios-cache-adapter</code>.</li></ul><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><h3 id="axios-cache-adapter" tabindex="-1">axios-cache-adapter <a class="header-anchor" href="#axios-cache-adapter" aria-label="Permalink to &quot;axios-cache-adapter&quot;">​</a></h3><p>This library was heavily inspired by axios-cache-adapter. That library was good, but it is now unmaintained and has many unresolved issues. It is also larger than this library, with fewer features and lower performance.</p><h3 id="fetch-with-a-state-management-library" tabindex="-1">Fetch with a state management library <a class="header-anchor" href="#fetch-with-a-state-management-library" aria-label="Permalink to &quot;Fetch with a state management library&quot;">​</a></h3><p>This library was built specifically for axios and manages its own storage, request deduplication and HTTP caching headers, which hand-rolled caches rarely cover. For state management libraries and similar tools, <a href="https://arthur.place/implications-of-cache-or-state" target="_blank" rel="noreferrer">this blog post</a> explains why a cache is a better architectural fit than state.</p>',15)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
